"""B: offline antenna error and cancellation for3m,10m; no labels online."""
import os,json
from pathlib import Path
import numpy as np
from common import *
OUT=Path(os.environ['LIO_GINS_S10_OUT']);eventrows=[];policyrows=[];pointrows=[];documents=[]
def stats(v):
 h=np.linalg.norm(v[:,:2],axis=1)
 return {'n':len(v),'horizontal_RMSE_m':float(np.sqrt(np.mean(h*h))) if len(v) else None,'horizontal_median_m':float(np.median(h)) if len(v) else None,'horizontal_P95_m':float(np.percentile(h,95)) if len(v) else None,'horizontal_Max_m':float(max(h)) if len(v) else None,'signed_mean_N_m':float(np.mean(v[:,0])) if len(v) else None,'signed_mean_E_m':float(np.mean(v[:,1])) if len(v) else None}
for route,item in catalog().items():
 c=route_context(route);natural=load_gnss(c['stress']/'natural.csv');nmap={int(g[0]):g for g in natural};route_records=[]
 for case in ['loss30_bias3','loss30_bias10']:
  gnss=load_gnss(c['stress']/(case+'.csv'));gmap={int(g[0]):g for g in gnss};assert all(np.array_equal(g[[0,1,5,6,7]],nmap[int(g[0])][[0,1,5,6,7]]) for g in gnss)
  allinjected=set()
  for i,event in enumerate(events(route,case)):
   returned=event['recovery_start_sow'];amp=event['fault_parameters']['recovery_bias_m'];g=gnss[(gnss[:,1]>=returned)&(gnss[:,1]<returned+90)];assert len(g)==90 and np.all(np.diff(g[:,1])==1)
   n=np.vstack([nmap[int(x[0])] for x in g]);truth=antenna_truth(c,g[:,1]);raw=n[:,2:5]-truth;inj=g[:,2:5]-truth;delta=g[:,2:5]-n[:,2:5];assert np.max(abs(np.linalg.norm(delta,axis=1)-amp))<1e-8
   ids={int(x[0]) for x in g};allinjected|=ids;deleted=[int(x[0]) for x in natural if event['fault_start_sow']<=x[1]<event['fault_end_sow']];assert len(deleted)==30 and not any(x in gmap for x in deleted)
   h0=np.linalg.norm(raw[:,:2],axis=1);h1=np.linalg.norm(inj[:,:2],axis=1);cancels=h1<h0
   r={'route':route,'same_bag_sensitivity':item['repeat'],'case':case,'event':i,'direction':['N','E','NE'][i],'amp_m':amp,'return_sow':returned,'rows_aligned':len(g),'deleted_rows_verified':len(deleted),'cancellation_rows':int(sum(cancels)),'natural_receiver_RMSE_m':stats(raw)['horizontal_RMSE_m'],'injected_receiver_RMSE_m':stats(inj)['horizontal_RMSE_m'],'natural_receiver_P95_m':stats(raw)['horizontal_P95_m'],'injected_receiver_P95_m':stats(inj)['horizontal_P95_m'],'natural_mean_N_m':stats(raw)['signed_mean_N_m'],'natural_mean_E_m':stats(raw)['signed_mean_E_m'],'injected_mean_N_m':stats(inj)['signed_mean_N_m'],'injected_mean_E_m':stats(inj)['signed_mean_E_m'],'direction_delta_N_m':float(np.mean(delta[:,0])),'direction_delta_E_m':float(np.mean(delta[:,1])),'reference_source':'GNSS/INS OEM719/navigation-grade' if route in ['street00','playground00','building02'] else 'MM/INS AT128-shared' if route in ['parking00','building01'] else 'GNSS/INS/navigation-grade','coordinates':'initialization-conditioned local NED antenna, offline lever-arm ZYX/Slerp; not absolute geodetic origin','reference_SHA':sha(c['reference_path']),'natural_SHA':sha(c['stress']/'natural.csv'),'biased_SHA':sha(c['stress']/(case+'.csv')),'initialization_SHA':sha(c['icp'])};eventrows.append(r);route_records.append(r)
   for j,x in enumerate(g):pointrows.append({'route':route,'case':case,'event':i,'original_gnss_id':int(x[0]),'measurement_sow':x[1],'natural_error_N_m':raw[j,0],'natural_error_E_m':raw[j,1],'injected_error_N_m':inj[j,0],'injected_error_E_m':inj[j,1],'natural_horizontal_error_m':h0[j],'injected_horizontal_error_m':h1[j],'injection_reduces_error':bool(cancels[j])})
   for method in METHODS:
    source=item['rows'][(method,case)];u=updates(str(resolve(source['backend'])));umap={x['original_gnss_id']:x for x in u};assert ids<=umap.keys();mask=np.array([umap[int(x[0])]['accepted'] for x in g],bool);a=stats(inj[mask]);rej=stats(inj[~mask])
    policyrows.append({'route':route,'case':case,'event':i,'method':method,'injected_exposed':len(g),'injected_accepted':int(sum(mask)),'accepted_cancellation_rows':int(sum(mask&cancels)),'rejected_cancellation_rows':int(sum(~mask&cancels)),'accepted_actual_RMSE_m':a['horizontal_RMSE_m'],'accepted_actual_P95_m':a['horizontal_P95_m'],'rejected_actual_RMSE_m':rej['horizontal_RMSE_m'],'rejected_actual_P95_m':rej['horizontal_P95_m'],'empty_group_is_missing':True,'backend_run':str(resolve(source['backend'])),'updates_SHA':sha(resolve(source['backend'])/'per_update.jsonl')})
  assert all(np.linalg.norm(x[2:5]-nmap[int(x[0])][2:5])<1e-8 for x in gnss if int(x[0]) not in allinjected)
 json_write(OUT/(route+'_injection_audit.json'),{'events':route_records,'offline_only':True,'no_parameters_or_observations_modified':True,'data_identity':{'event_manifest':sha(c['stress']/'event_manifest.json'),'reference':sha(c['reference_path']),'initial_condition':sha(c['icp'])}})
 print(json.dumps({'route':route,'3m_cancellation_rows':sum(x['cancellation_rows'] for x in route_records if x['case']=='loss30_bias3')}),flush=True)
csv_write(OUT/'injection_bias3_audit.csv',eventrows);csv_write(OUT/'injection_acceptance_audit.csv',policyrows);csv_write(OUT/'injection_row_labels_offline.csv',pointrows)
lines=['# B3m injection/error cancellation audit','', 'All six routes plus separately labeled building00 repeat, all fixed3m and10m events and all19 policies. Each event90 IDs, each deleted interval30 IDs. Natural and disturbed rows match original ID/time/std; only position displacement changes. Reference/lever-arm rotation is offline only; no estimator, observation, weight or threshold modified. A3m displacement does not establish an actual3m absolute GNSS error.','', '|Route|Event|3m cancellation/90|Raw receiver RMSE|Injected receiver RMSE|10m cancellation/90|','|---|---:|---:|---:|---:|---:|']
for r in [x for x in eventrows if x['case']=='loss30_bias3']:
 other=next(x for x in eventrows if x['route']==r['route'] and x['event']==r['event'] and x['case']=='loss30_bias10');lines.append(f"|{r['route']}|{r['event']}|{r['cancellation_rows']}/90|{r['natural_receiver_RMSE_m']:.6f}|{r['injected_receiver_RMSE_m']:.6f}|{other['cancellation_rows']}/90|")
lines+=['','Per-policy accepted and rejected actual-error distributions are in injection_acceptance_audit.csv; empty accepted/rejected groups are null, never0. Full per-original-ID labels are offline diagnostics only. Controlled injection acceptance is not natural fault-detection probability. Reference errors may correlate with GNSS; prior MM/INS also shares AT128. Known initialization and local alignment condition the receiver-error values. Cancellation requires route/event-specific interpretation; no cancellation-based case exclusion or retrospective tuning is allowed.']
(OUT/'INJECTION_BIAS3_AUDIT.md').write_text('\n'.join(lines)+'\n')
json_write(OUT/'injection_audit_manifest.json',{'event_records':len(eventrows),'policy_records':len(policyrows),'labeled_rows':len(pointrows),'all6routes_and_repeat':True,'bias3_cancellation_audited':True,'offline_labels_only':True,'independent_confirmatory_gain_supported':False,'script_SHA':sha(__file__),'common_SHA':sha(ROOT/'experiments/s10/common.py')})
